using Microsoft.EntityFrameworkCore;
class AppDbContext : DbContext
{
    public DbSet<Order> Orders => Set<Order>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // EF Core 9 breaking change: HasData() now uses UTC for seeding DateTime values.
        // Use a fixed UTC value instead of DateTime.UtcNow for deterministic migrations.
        modelBuilder.Entity<Order>().HasData(
            new Order { Id = 1, CreatedAt = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc) });
    }
}
class Order { public int Id { get; set; } public DateTime CreatedAt { get; set; } }

// --- Cosmos DB context demonstrating EF Core 9 breaking changes ---
class CosmosDbContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();

    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
    {
        optionsBuilder.UseCosmos(
            "AccountEndpoint=https://localhost:8081/;AccountKey=placeholder",
            "CatalogDb");
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Breaking change 1: EF Core 9 Cosmos provider renamed the discriminator
        // property from "Discriminator" to "$type". Existing documents still use
        // "Discriminator", so we must explicitly configure backwards compatibility.
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");
            entity.HasPartitionKey(p => p.CategoryId);

            // Preserve legacy discriminator property name for existing documents
            entity.HasDiscriminator<string>("Discriminator")
                  .HasValue<Product>("Product")
                  .HasValue<DiscontinuedProduct>("DiscontinuedProduct");
        });

        modelBuilder.Entity<DiscontinuedProduct>();
    }
}

class Product
{
    public string Id { get; set; } = default!;
    public string CategoryId { get; set; } = default!;
    public string Name { get; set; } = default!;
}

class DiscontinuedProduct : Product
{
    public DateTime DiscontinuedDate { get; set; }
}

// Breaking change 2: EF Core 9 Cosmos provider removed synchronous I/O support.
// All queries/saves MUST be async. Example fix:
class CosmosQueryService
{
    // WRONG in EF Core 9 (throws InvalidOperationException):
    // var products = db.Products.ToList();

    // CORRECT — use async methods:
    public async Task<List<Product>> GetProductsAsync(CosmosDbContext db)
    {
        return await db.Products.ToListAsync();
    }

    public async Task SaveProductAsync(CosmosDbContext db, Product product)
    {
        db.Products.Add(product);
        await db.SaveChangesAsync();
    }
}

